long long countDerangements(int n, int position, vector<char>& used) {
    if (position == n) return 1;
    long long total = 0;
    for (int value = 0; value < n; value++) {
        if (!used[value] && value != position) {
            used[value] = 1;
            total += countDerangements(n, position + 1, used);
            used[value] = 0;
        }
    }
    return total;
}

